window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2e83a7f969db8843"]={"versions": [{"id": "FIG-2e83a7f969db8843", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilschritts innerhalb des AUTOSAR E2E-Protokolls (End-to-End Communication Protection Library). Das Diagramm stellt das Verhalten des Prüfschritts „Read Message Type“ innerhalb der Prüffunktion <code>E2E_P04mCheck()</code> für das E2E-Profil 4m (Client- und Serverseite) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext / Aufrufkontext:</strong> <code>E2E_P04mCheck()</code> (als Sub-Aktivität bzw. aufgerufene Funktion gekennzeichnet).\n</li><li><strong>Eingangsdaten:</strong> Datenarray <code>Data</code> an Indexposition <code>[Offset+12]</code>.\n</li><li><strong>Lokale Variable / Ausgangsdatum:</strong> <code>ReceivedMessageType</code> vom Typ <code>uint8</code>.\n</li><li><strong>Aktionen:</strong> Einzelner Aktionsknoten zur Extraktion und Zuweisung des 2-Bit-Nachrichtentyps:\n <code>Copy 2-bit MessageType from the bits 0 and 1 of byte Data [Offset+12] in Big Endian order on uint8 local variable ReceivedMessageType, i.e., ReceivedMessageType = (Data [Offset+12] &amp; 0xC0) &gt;&gt; 6</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Startknoten (Initial Node).\n</li><li>Kontrollfluss führt direkt zum Aktionsknoten zur Extraktion des Nachrichtentyps.\n</li><li>Der 2-Bit-Wert <code>MessageType</code> wird aus den höchstwertigen Bits 0 und 1 des Bytes <code>Data[Offset+12]</code> (gemäß Big-Endian-Bitnummerierung) über die Bitmaskierung <code>&amp; 0xC0</code> und Rechtsshift um 6 Bit isoliert und in die lokale Variable <code>ReceivedMessageType</code> geschrieben.\n</li><li>Der Kontrollfluss geht unmittelbar in den Endknoten (Activity Final Node) über, womit dieser Schritt abgeschlossen ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Teilschritt ist eine normative Anforderung (<code>[PRS_E2E_00778]</code>) im Rahmen der E2E-Profil-4m-Prüfung sowohl auf Client- als auch auf Serverseite. Bei der Implementierung ist auf die Big-Endian-Bitnummerierung zu achten (Bit 0 entspricht dem MSB mit Wertigkeit <code>0x80</code>, Bit 1 <code>0x40</code>). Die Berechnung entspricht exakt dem bitweisen Ausdruck <code>(Data[Offset+12] &amp; 0xC0) &gt;&gt; 6</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e3a7d8faf723e71a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilschritts innerhalb des AUTOSAR E2E-Protokolls (End-to-End Communication Protection Library). Das Diagramm stellt das Verhalten des Prüfschritts „Read Message Type“ innerhalb der Prüffunktion <code>E2E_P04mCheck()</code> für das E2E-Profil 4m (Client- und Serverseite) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext / Aufrufkontext:</strong> <code>E2E_P04mCheck()</code> (als Sub-Aktivität bzw. aufgerufene Funktion gekennzeichnet).\n</li><li><strong>Eingangsdaten:</strong> Datenarray <code>Data</code> an Indexposition <code>[Offset+12]</code>.\n</li><li><strong>Lokale Variable / Ausgangsdatum:</strong> <code>ReceivedMessageType</code> vom Typ <code>uint8</code>.\n</li><li><strong>Aktionen:</strong> Einzelner Aktionsknoten zur Extraktion und Zuweisung des 2-Bit-Nachrichtentyps:\n <code>Copy 2-bit MessageType from the bits 0 and 1 of byte Data [Offset+12] in Big Endian order on uint8 local variable ReceivedMessageType, i.e., ReceivedMessageType = (Data [Offset+12] &amp; 0xC0) &gt;&gt; 6</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Startknoten (Initial Node).\n</li><li>Kontrollfluss führt direkt zum Aktionsknoten zur Extraktion des Nachrichtentyps.\n</li><li>Der 2-Bit-Wert <code>MessageType</code> wird aus den höchstwertigen Bits 0 und 1 des Bytes <code>Data[Offset+12]</code> (gemäß Big-Endian-Bitnummerierung) über die Bitmaskierung <code>&amp; 0xC0</code> und Rechtsshift um 6 Bit isoliert und in die lokale Variable <code>ReceivedMessageType</code> geschrieben.\n</li><li>Der Kontrollfluss geht unmittelbar in den Endknoten (Activity Final Node) über, womit dieser Schritt abgeschlossen ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Teilschritt ist eine normative Anforderung (<code>[PRS_E2E_00778]</code>) im Rahmen der E2E-Profil-4m-Prüfung sowohl auf Client- als auch auf Serverseite. Bei der Implementierung ist auf die Big-Endian-Bitnummerierung zu achten (Bit 0 entspricht dem MSB mit Wertigkeit <code>0x80</code>, Bit 1 <code>0x40</code>). Die Berechnung entspricht exakt dem bitweisen Ausdruck <code>(Data[Offset+12] &amp; 0xC0) &gt;&gt; 6</code>.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2e83a7f969db8843", "to": "FIG-e3a7d8faf723e71a", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
